\begin{align*}
	\hat{h}_1&=\begin{cases}
		0 & \text{if } h_1 < l^h_1\\
		0 & \text{if } h_1 > u^h_1\\
		h_1 & \text{if } h_1\geq l^h_1 \text{ and } h_1\leq u^h_1
	\end{cases}\\
o_1&= \hat{h}_1\cdot w^o_1
\end{align*}

